-- Analytical View: FOXA1 Mutation and Expression---- Purpose:-- Integrate FOXA1 mutation status and expression-- at the sample level while preserving histological subtype.---- Grain:-- One row per sample.---- Source:-- analytical.dim_sample-- analytical.fact_mutation-- analytical.fact_expressionCREATE OR REPLACE VIEW analytical.vw_foxa1_mutation_expression ASSELECT    s.sample_id,    s.histological_type,    m.mutation_status,    e.expression_levelFROM analytical.dim_sample AS sINNER JOIN analytical.fact_mutation AS m    ON s.sample_id = m.sample_id   AND m.gene_name = 'FOXA1'INNER JOIN analytical.fact_expression AS e    ON s.sample_id = e.sample_id   AND e.gene_name = 'FOXA1';